 83	/// A system-wide hotkey through Carbon, which needs no Accessibility permission.
 84	final class HotKey {
 85	    private var ref: EventHotKeyRef?
 86	    private var handler: EventHandlerRef?
 87	    private let action: () -> Void
 88	
 89	    init(keyCode: UInt32, modifiers: UInt32, action: @escaping () -> Void) {
 90	        self.action = action
 91	        var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
 92	        let context = Unmanaged.passUnretained(self).toOpaque()
 93	        InstallEventHandler(GetApplicationEventTarget(), { _, _, userData in
 94	            guard let userData else { return OSStatus(noErr) }
 95	            Unmanaged<HotKey>.fromOpaque(userData).takeUnretainedValue().action()
 96	            return OSStatus(noErr)
 97	        }, 1, &spec, context, &handler)
 98	        let hotKeyID = EventHotKeyID(signature: OSType(0x4D45_5659), id: 1) // "MEVY"
 99	        RegisterEventHotKey(keyCode, modifiers, hotKeyID, GetApplicationEventTarget(), 0, &ref)
100	    }
101	
102	    deinit {
103	        if let ref { UnregisterEventHotKey(ref) }
104	        if let handler { RemoveEventHandler(handler) }
105	    }
106	}
