108	final class SearchModel: ObservableObject {
109	    @Published var query = "" { didSet { run() } }
110	    @Published var hits: [SearchHit] = []
111	    @Published var message = ""
112	    @Published private(set) var sort = SortKey.name
113	    @Published private(set) var descending = false
114	
115	    /// Changes the sort and searches once (setting the two fields separately would search twice).
116	    func setSort(_ key: SortKey, descending: Bool) {
117	        sort = key
118	        self.descending = descending
119	        run()
120	    }
121	    /// What the scope menu offers: All, This Mac, Cloud, each cloud account, then each indexed drive.
122	    @Published var scopes: [SearchScope] = [.all]
123	    @Published var scope = SearchScope.all {
124	        didSet {
125	            // A fallback while a saved drive is unplugged must not forget that choice.
126	            if !restoring { UserDefaults.standard.set(scope.id, forKey: SearchModel.scopeKey) }
127	            run()
128	        }
129	    }
130	    private var restoring = false
131	    /// The file-type menu at the end of the search box (Everything's Search > filters).
132	    @Published var filter: FileFilter = FileFilter(rawValue: UserDefaults.standard.string(forKey: SearchModel.filterKey) ?? "")
133	        ?? .everything {
134	        didSet {
135	            UserDefaults.standard.set(filter.rawValue, forKey: SearchModel.filterKey)
136	            run()
137	        }
138	    }
139	    private static let filterKey = "searchFilter"
140	    /// Temp and generated files (node_modules, .git, caches, *.tmp...) are hidden unless ticked.
141	    @Published var showTemp = UserDefaults.standard.bool(forKey: SearchModel.showTempKey) {
142	        didSet {
143	            UserDefaults.standard.set(showTemp, forKey: SearchModel.showTempKey)
144	            run()
145	        }
146	    }
147	    private static let showTempKey = "showTempFiles"
148	
149	    private static let scopeKey = "searchScope"
150	    private let queue = DispatchQueue(label: "MacEverything.app.search")
151	    private var generation = 0
152	
153	    init() {
154	        refreshScopes()
155	    }
156	
157	    /// Rebuilds the scope menu from the daemon's roots, so a drive plugged in or out shows up
158	    /// the next time the window opens. Restores the last choice when it is still offered.
159	    func refreshScopes() {
160	        queue.async {
161	            let roots = (try? IPC.send(IPCRequest(command: "status")))?.status?.roots ?? []
162	            let choices = SearchScope.choices(roots: roots)
163	            DispatchQueue.main.async {
164	                self.scopes = choices
165	                let saved = UserDefaults.standard.string(forKey: SearchModel.scopeKey).flatMap(SearchScope.init(id:))
166	                let wanted = saved ?? self.scope
167	                let next = choices.contains(wanted) ? wanted : .all
168	                if next != self.scope {
169	                    self.restoring = true
170	                    self.scope = next // runs the search
171	                    self.restoring = false
172	                } else {
173	                    self.run() // results and the footer are fresh each time the window opens
174	                }
175	            }
176	        }
177	    }
178	
179	    func run() {
180	        generation += 1
181	        let gen = generation
182	        let request = IPCRequest(command: "search", query: query, limit: 500, sort: sort, descending: descending,
183	                                 scope: [scope.query, filter.query, showTemp ? "" : "!temp:"]
184	                                     .filter { !$0.isEmpty }.joined(separator: " "))
185	        queue.async {
186	            let text: String
187	            var newHits: [SearchHit] = []
188	            do {
189	                let response = try IPC.send(request)
190	                if let r = response.result {
191	                    newHits = r.hits
192	                    text = "\(r.total.formatted()) objects  ·  \(String(format: "%.1f", r.milliseconds)) ms"
193	                } else {
194	                    text = response.error ?? "Search failed"
195	                }
196	            } catch IPCError.notRunning(_) {
197	                // Usually the daemon restarting (an install, a login): try again shortly
198	                // instead of leaving the error up until the next keystroke.
199	                text = "Waiting for the index service to start…"
200	                DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
201	                    if gen == self.generation { self.run() }
202	                }
203	            } catch {
204	                text = "\(error)"
205	            }
206	            DispatchQueue.main.async {
207	                guard gen == self.generation else { return }
208	                self.hits = newHits
209	                self.message = text
210	            }
211	        }
212	    }
213	}
