364	    private static func kind(_ hit: SearchHit) -> String {
365	        let ext = (hit.name as NSString).pathExtension
366	        if hit.isDirectory { return ext.isEmpty ? "Folder" : (UTType(filenameExtension: ext)?.localizedDescription ?? "Folder") }
367	        if ext.isEmpty { return "Document" }
368	        return UTType(filenameExtension: ext)?.localizedDescription ?? ext.uppercased() + " file"
369	    }
