371	    /// Sorting from the headers and the row menu, shared by both tables.
372	    private func withBehavior<T: View>(_ table: T) -> some View {
373	        table
374	            // Clicking a header sorts by it; clicking again flips the order. The daemon does the
375	            // sorting, so it covers every match, not only the rows on screen.
376	            .onChange(of: sortOrder) { order in
377	                guard let first = order.first else { return }
378	                let column = first.keyPath
379	                let key: SortKey
380	                if column == \SearchHit.path as PartialKeyPath<SearchHit> {
381	                    key = .path
382	                } else if column == \SearchHit.size as PartialKeyPath<SearchHit> {
383	                    key = .size
384	                } else if column == \SearchHit.modified as PartialKeyPath<SearchHit> {
385	                    key = .modified
386	                } else {
387	                    key = .name
388	                }
389	                let descending = first.order == .reverse
390	                if model.sort != key || model.descending != descending {
391	                    model.setSort(key, descending: descending)
392	                }
393	            }
394	            .contextMenu(forSelectionType: String.self) { paths in
395	                Button("Open") { open(paths, reveal: false) }
396	                Button("Reveal in Finder") { open(paths, reveal: true) }
397	                Button("Copy Path") { copy(paths) }
398	            } primaryAction: { paths in
399	                open(paths, reveal: false)
400	            }
401	    }
