413	    private func open(_ paths: [String], reveal: Bool) {
414	        let urls = paths.map { URL(fileURLWithPath: $0) }
415	        if reveal {
416	            NSWorkspace.shared.activateFileViewerSelecting(urls)
417	        } else {
418	            urls.forEach { NSWorkspace.shared.open($0) }
419	        }
420	    }
