429	final class LocationsModel: ObservableObject {
430	    @Published var indexed: [String] = []
431	    @Published var added: [String] = []
432	    @Published var message = ""
433	
434	    func refresh() {
435	        let config = ServiceConfig.load()
436	        added = config.extraRoots ?? []
437	        DispatchQueue.global().async {
438	            let roots = (try? IPC.send(IPCRequest(command: "status")))?.status?.roots
439	            DispatchQueue.main.async { self.indexed = roots ?? config.resolvedRoots() }
440	        }
441	    }
442	
443	    func choose() {
444	        let open = NSOpenPanel()
445	        open.canChooseDirectories = true
446	        open.canChooseFiles = false
447	        open.allowsMultipleSelection = false
448	        open.prompt = "Add"
449	        open.message = "Choose a folder, drive or network share to index"
450	        guard open.runModal() == .OK, let url = open.url else { return }
451	        add(url.path)
452	    }
453	
454	    func add(_ path: String) {
455	        var config = ServiceConfig.load()
456	        let new = IndexService.canonical(path)
457	        let current = IndexService.normalizeRoots(config.resolvedRoots(), exclusions: config.exclusionSet)
458	        let after = IndexService.normalizeRoots(current + [new], exclusions: config.exclusionSet)
459	        guard after != current else {
460	            let outer = current.first { $0 == "/" || new == $0 || new.hasPrefix($0 + "/") } ?? "/"
461	            message = "Already indexed: \(new) is inside \(outer)."
462	            return
463	        }
464	        config.extraRoots = (config.extraRoots ?? []) + [new]
465	        save(config, done: "Added \(new). It is being scanned and will appear in results shortly.")
466	    }
467	
468	    func remove(_ path: String) {
469	        var config = ServiceConfig.load()
470	        config.extraRoots = (config.extraRoots ?? []).filter { $0 != path }
471	        if config.extraRoots?.isEmpty == true { config.extraRoots = nil }
472	        save(config, done: "Removed \(path).")
473	    }
474	
475	    private func save(_ config: ServiceConfig, done: String) {
476	        do {
477	            try config.save()
478	        } catch {
479	            message = "Could not save the settings: \(error.localizedDescription)"
480	            return
481	        }
482	        // The daemon restarts with the new list, keeps what it already indexed, and scans only
483	        // the new location.
484	        _ = try? IPC.send(IPCRequest(command: "reload"))
485	        message = done
486	        DispatchQueue.main.asyncAfter(deadline: .now() + 15) { self.refresh() }
487	        refresh()
488	    }
489	}
