3	     3	/// A parsed search. Groups are ANDed; the alternatives inside a group are ORed.
4	     4	public struct Query {
5	     5	    public var groups: [[Term]]
6	     6	
7	     7	    public init(groups: [[Term]]) { self.groups = groups }
8	     8	
9	     9	    public enum Term: Equatable {
10	    10	        case contains([UInt8], negated: Bool)          // lowercase bytes, matched against the name
11	    11	        case pathContains([UInt8], negated: Bool)      // lowercase bytes, matched against the full path
12	    12	        case glob([UInt8], negated: Bool)              // lowercase wildcard pattern, whole name
13	    13	        case regex(String, negated: Bool)
14	    14	        case ext([[UInt8]], negated: Bool)             // ".pdf" style lowercase suffixes
15	    15	        case size(Comparison, Int64, negated: Bool)
16	    16	        case modified(Comparison, Int64, Int64, negated: Bool) // [start, end) seconds since 1970
17	    17	        case filesOnly
18	    18	        case foldersOnly
19	    19	        /// Temp and generated files, and everything inside temp folders (see TempFiles).
20	    20	        case temp(negated: Bool)
21	    21	    }
22	    22	
23	    23	    public enum Comparison: Equatable { case less, lessOrEqual, greater, greaterOrEqual, equal }
24	    24	
25	    25	    public var isEmpty: Bool { groups.isEmpty }
26	    26	
27	    27	    /// Parses Everything-style syntax: `foo bar`, `"exact phrase"`, `a | b`, `!skip`, `*.pdf`,
28	    28	    /// `ext:pdf;docx`, `path:Football`, `drive:Work`, `size:>1gb`, `dm:today`, `regex:^IMG_\d+`,
29	    29	    /// `file:`, `folder:`.
30	    30	    public static func parse(_ text: String, now: Date = Date(), calendar: Calendar = .current) -> Query {
31	    31	        var groups: [[Term]] = []
32	    32	        var joinNext = false
