126	   126	    static func comparison(_ s: String) -> (Comparison, String) {
127	   127	        if s.hasPrefix(">=") { return (.greaterOrEqual, String(s.dropFirst(2))) }
128	   128	        if s.hasPrefix("<=") { return (.lessOrEqual, String(s.dropFirst(2))) }
