204	    37	/// A query flattened into plain values, so the per-record loop does no reference counting.
205	    38	struct CompiledQuery {
206	    39	    struct Term {
207	    40	        var kind: UInt8      // see Kind
208	    41	        var negated: Bool
209	    42	        var start: Int       // byte offset into `bytes`, slot index (ext) or regex index
210	    43	        var length: Int      // byte length, or slot count (ext)
211	    44	        var cmp: UInt8
212	    45	        var a: Int64
213	    46	        var b: Int64
214	    47	    }
215	    48	
216	    49	    enum Kind {
217	    50	        static let contains: UInt8 = 0, path: UInt8 = 1, glob: UInt8 = 2, regex: UInt8 = 3, ext: UInt8 = 4
218	    51	        static let size: UInt8 = 5, modified: UInt8 = 6, files: UInt8 = 7, folders: UInt8 = 8
219	    52	        static let temp: UInt8 = 9
220	    53	    }
221	    54	
222	    55	    var terms: [Term] = []
223	    56	    var groupStart: [Int] = []
224	    57	    var groupCount: [Int] = []
225	    58	    var bytes: [UInt8] = []
226	    59	    var slotStart: [Int] = []
227	    60	    var slotLength: [Int] = []
228	    61	    var regexes: [NSRegularExpression?] = []
229	    62	    /// Same patterns compiled to run over newline-joined names; nil when not line-safe.
230	    63	    var lineRegexes: [NSRegularExpression?] = []
231	    64	    /// Per regex: the required literal's offset and length in `bytes` (length 0 when none).
232	    65	    var regexLiteralStart: [Int] = []
233	    66	    var regexLiteralLength: [Int] = []
234	    67	    /// Index into `terms` of each path: term; its PathTable is built per scan.
235	    68	    var pathTerms: [Int] = []
236	    69	    var hasRegex = false
237	    70	    var hasTemp = false
238	    71	
239	    72	    init(_ query: Query) {
240	    73	        for group in query.groups {
241	    74	            groupStart.append(terms.count)
242	    75	            groupCount.append(group.count)
243	    76	            for term in group { terms.append(compile(term)) }
244	    77	        }
245	    78	    }
246	    79	
247	    80	    private mutating func addBytes(_ b: [UInt8]) -> Int {
248	    81	        let start = bytes.count
249	    82	        bytes.append(contentsOf: b)
250	    83	        return start
251	    84	    }
