253	    86	    private static func cmpCode(_ c: Query.Comparison) -> UInt8 {
254	    87	        switch c {
255	    88	        case .less: return 0
256	    89	        case .lessOrEqual: return 1
257	    90	        case .greater: return 2
258	    91	        case .greaterOrEqual: return 3
259	    92	        case .equal: return 4
260	    93	        }
261	    94	    }
