263	    96	    private mutating func compile(_ term: Query.Term) -> Term {
264	    97	        var t = Term(kind: 0, negated: false, start: 0, length: 0, cmp: 0, a: 0, b: 0)
265	    98	        switch term {
266	    99	        case let .contains(n, neg):
267	   100	            t.kind = Kind.contains; t.negated = neg; t.start = addBytes(n); t.length = n.count
268	   101	        case let .pathContains(n, neg):
269	   102	            t.kind = Kind.path; t.negated = neg; t.start = addBytes(n); t.length = n.count
270	   103	            t.b = Int64(pathTerms.count) // which PathTable
271	   104	            pathTerms.append(terms.count)
272	   105	        case let .glob(n, neg):
273	   106	            t.kind = Kind.glob; t.negated = neg; t.start = addBytes(n); t.length = n.count
274	   107	        case let .regex(pattern, neg):
275	   108	            t.kind = Kind.regex; t.negated = neg; t.start = regexes.count
276	   109	            regexes.append(try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]))
277	   110	            lineRegexes.append(RegexSupport.isLineSafe(pattern)
278	   111	                ? try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive, .anchorsMatchLines])
