285	   118	                t.b = Int64(lit.count)
286	   119	            }
287	   120	            regexLiteralStart.append(Int(t.a))
288	   121	            regexLiteralLength.append(Int(t.b))
289	   122	        case let .ext(list, neg):
290	   123	            t.kind = Kind.ext; t.negated = neg; t.start = slotStart.count; t.length = list.count
291	   124	            for suffix in list {
292	   125	                slotStart.append(addBytes(suffix))
293	   126	                slotLength.append(suffix.count)
294	   127	            }
295	   128	        case let .size(cmp, value, neg):
296	   129	            t.kind = Kind.size; t.negated = neg; t.cmp = CompiledQuery.cmpCode(cmp); t.a = value
297	   130	        case let .modified(cmp, start, end, neg):
298	   131	            t.kind = Kind.modified; t.negated = neg; t.cmp = CompiledQuery.cmpCode(cmp); t.a = start; t.b = end
299	   132	        case .filesOnly:
300	   133	            t.kind = Kind.files
301	   134	        case .foldersOnly:
302	   135	            t.kind = Kind.folders
303	   136	        case let .temp(neg):
304	   137	            t.kind = Kind.temp; t.negated = neg
305	   138	            hasTemp = true
306	   139	        }
307	   140	        return t
308	   141	    }
309	   142	}
