313	   146	extension FileIndex {
314	   147	    /// Runs `query` across every live record, split over all CPU cores.
315	   148	    public func search(_ query: Query, options: SearchOptions = SearchOptions()) -> SearchResult {
316	   149	        let started = DispatchTime.now().uptimeNanoseconds
317	   150	        let matched = matchingIdsInIdOrder(query)
318	   151	        let total = matched.count
319	   152	        let offset = min(max(options.offset, 0), total)
320	   153	        let limit = max(options.limit, 0)
321	   154	        let end = limit >= total - offset ? total : offset + limit
322	   155	
323	   156	        let page: [Int32]
324	   157	        switch options.sort {
325	   158	        case .name:
326	   159	            page = Array(nameOrdered(matched, first: end, descending: options.descending)[offset..<end])
327	   160	        case .path:
328	   161	            let paths = matched.map { path(of: $0).lowercased() }
329	   162	            var idx = Array(0..<matched.count)
330	   163	            idx.sort { options.descending ? paths[$0] > paths[$1] : paths[$0] < paths[$1] }
331	   164	            page = idx[offset..<end].map { matched[$0] }
332	   165	        case .size, .modified:
333	   166	            let bySize = options.sort == .size
334	   167	            var sorted = matched
335	   168	            sorted.sort {
336	   169	                let ra = records[Int($0)], rb = records[Int($1)]
337	   170	                let a = bySize ? ra.size : ra.modified, b = bySize ? rb.size : rb.modified
338	   171	                return options.descending ? a > b : a < b
339	   172	            }
340	   173	            page = Array(sorted[offset..<end])
341	   174	        }
342	   175	
343	   176	        let hits = page.map { id -> SearchHit in
344	   177	            let r = records[Int(id)]
345	   178	            return SearchHit(path: path(of: id), name: name(of: id), isDirectory: r.isDirectory,
346	   179	                             size: r.size, modified: r.modified)
347	   180	        }
348	   181	        let ms = Double(DispatchTime.now().uptimeNanoseconds - started) / 1_000_000
349	   182	        return SearchResult(total: total, hits: hits, milliseconds: ms)
350	   183	    }
