358	   191	    /// The first `first` of `ids` in name order. Uses each id's rank in the presorted `order`
359	   192	    /// (a bitmap walk, no comparisons) and merges in ids added since the last sort.
360	   193	    func nameOrdered(_ ids: [Int32], first: Int, descending: Bool) -> [Int32] {
361	   194	        if first == 0 { return [] }
362	   195	        var unranked: [Int32] = []
363	   196	        var bits = [UInt64](repeating: 0, count: (order.count + 63) / 64)
364	   197	        for id in ids {
365	   198	            let rk = rank[Int(id)]
366	   199	            if rk >= 0 {
367	   200	                bits[Int(rk) >> 6] |= 1 << UInt64(rk & 63)
368	   201	            } else {
369	   202	                unranked.append(id)
370	   203	            }
371	   204	        }
372	   205	        var ranked: [Int32] = []
373	   206	        ranked.reserveCapacity(min(first, ids.count))
374	   207	        if descending {
375	   208	            var w = bits.count - 1
376	   209	            while w >= 0 && ranked.count < first {
377	   210	                var word = bits[w]
378	   211	                while word != 0 && ranked.count < first {
379	   212	                    let bit = 63 - word.leadingZeroBitCount
380	   213	                    ranked.append(order[w * 64 + bit])
381	   214	                    word &= ~(UInt64(1) << UInt64(bit))
382	   215	                }
383	   216	                w -= 1
384	   217	            }
385	   218	        } else {
386	   219	            var w = 0
387	   220	            while w < bits.count && ranked.count < first {
388	   221	                var word = bits[w]
389	   222	                while word != 0 && ranked.count < first {
390	   223	                    let bit = word.trailingZeroBitCount
391	   224	                    ranked.append(order[w * 64 + bit])
392	   225	                    word &= word - 1
393	   226	                }
394	   227	                w += 1
395	   228	            }
396	   229	        }
397	   230	        if unranked.isEmpty { return ranked }
398	   231	        unranked.sort(by: lowerBytesLess)
399	   232	        if descending { unranked.reverse() }
400	   233	        var out: [Int32] = []
401	   234	        out.reserveCapacity(min(first, ranked.count + unranked.count))
402	   235	        var i = 0, j = 0
403	   236	        while out.count < first && (i < ranked.count || j < unranked.count) {
404	   237	            let takeUnranked: Bool
405	   238	            if i >= ranked.count {
406	   239	                takeUnranked = true
407	   240	            } else if j >= unranked.count {
408	   241	                takeUnranked = false
409	   242	            } else {
410	   243	                takeUnranked = descending ? lowerBytesLess(ranked[i], unranked[j])
411	   244	                                          : lowerBytesLess(unranked[j], ranked[i])
412	   245	            }
413	   246	            if takeUnranked { out.append(unranked[j]); j += 1 } else { out.append(ranked[i]); i += 1 }
414	   247	        }
415	   248	        return out
416	   249	    }
