426	   259	        var partial = [[Int32]](repeating: [], count: chunkCount)
427	   260	        let temp = compiled.hasTemp ? tempMask() : []
428	   261	
429	   262	        records.withUnsafeBufferPointer { recs in
430	   263	        lowerNames.withUnsafeBufferPointer { lower in
431	   264	        compiled.terms.withUnsafeBufferPointer { terms in
432	   265	        compiled.bytes.withUnsafeBufferPointer { qbytes in
433	   266	        compiled.slotStart.withUnsafeBufferPointer { slotStart in
434	   267	        compiled.slotLength.withUnsafeBufferPointer { slotLength in
435	   268	        compiled.groupStart.withUnsafeBufferPointer { groupStart in
436	   269	        compiled.groupCount.withUnsafeBufferPointer { groupCount in
437	   270	        temp.withUnsafeBufferPointer { tempMask in
438	   271	        partial.withUnsafeMutableBufferPointer { out in
439	   272	            // One table per path: term, built in a single pass before the parallel scan.
