443	   276	            let views = tables.map(\.view)
444	   277	            views.withUnsafeBufferPointer { pathViews in
445	   278	            let ctx = MatchContext(recs: recs, lower: lower, terms: terms, qbytes: qbytes,
446	   279	                                   slotStart: slotStart, slotLength: slotLength,
447	   280	                                   groupStart: groupStart, groupCount: groupCount,
448	   281	                                   regexes: compiled.regexes, pathViews: pathViews, temp: tempMask)
449	   282	            DispatchQueue.concurrentPerform(iterations: chunkCount) { chunk in
450	   283	                let lo = chunk * chunkSize
451	   284	                let hi = min(lo + chunkSize, count)
452	   285	                if lo >= hi { return }
453	   286	                var found: [Int32] = []
454	   287	                // Regex terms run once over the chunk's names joined by newlines; the result
455	   288	                // says, per name, match / no match / unknown (then matched on its own).
