601	   434	            s += 1; p += 1
602	   435	        } else if p < pLen && pattern[pStart + p] == star {
603	   436	            starP = p; starS = s; p += 1
604	   437	        } else if starP >= 0 {
605	   438	            p = starP + 1; starS += 1; s = starS
606	   439	        } else {
